# Get non-empty, non-comment lines
lines = [line.strip() for line in student_code.split('\n') if line.strip() and not line.strip().startswith('#')]

# Task 1: Check import
if not any('import pandas as pd' in line for line in lines):
    raise AssertionError('Task 1: Missing "import pandas as pd"')

# Task 2: Check pd.DataFrame() call
if not any('sales_df' in line and 'pd.DataFrame' in line for line in lines):
    raise AssertionError('Task 2: sales_df should use pd.DataFrame()')
if not any('pd.DataFrame(sales_data)' in line for line in lines):
    raise AssertionError('Task 2: Should pass sales_data dictionary to pd.DataFrame()')

# Task 3: Check .head(3) is used and printed (flexible format)
if not any('.head(3)' in line for line in lines):
    raise AssertionError('Task 3: Should use .head(3) method')
if not any(('print' in line and 'head(3)' in line) for line in lines):
    raise AssertionError('Task 3: Should print the result of .head(3)')

# Task 4: Check .dtypes is printed (flexible format)
if not any(('print' in line and '.dtypes' in line) for line in lines):
    raise AssertionError('Task 4: Should print sales_df.dtypes')

print('TEST_PASSED')
